package com.nook.mapper;
import com.nook.domain.SocialEntities.*; import com.nook.dto.ApiDtos.*; import com.nook.repository.SocialRepository; import org.springframework.stereotype.Component; import java.time.*; import java.time.temporal.ChronoUnit; import java.util.*;
@Component public class SocialMapper { private final SocialRepository repo; public SocialMapper(SocialRepository r){repo=r;} public int age(LocalDate d){return Period.between(d,LocalDate.now()).getYears();} public PhotoDto photo(Photo v){return new PhotoDto(v.id,v.url,v.position,v.primary);} public List<String> split(String value){return value==null||value.isBlank()?List.of():Arrays.stream(value.split(",")).filter(s->!s.isBlank()).toList();} public Me me(User u){Profile p=repo.profile(u.id);Preference x=repo.preference(u.id);return new Me(u.id,u.email,p.name,age(p.birthDate),p.birthDate,p.gender,p.bio,p.city,p.lookingFor,p.coffeePersonality,p.preferredPlan,p.preferredVibe,p.coffeesPerDay,p.favoriteCoffeeMoment,x.minAge,x.maxAge,x.maxDistanceKm,x.visible,u.hidden,p.onboardingComplete,repo.coffees(u.id),repo.photos(u.id).stream().map(this::photo).toList(),split(x.desiredGenders),split(x.intentions),split(x.preferredVibes),split(x.preferredMoments),split(x.meetingStyles));} public DiscoverProfile profile(UUID viewer,Profile p){Profile me=repo.profile(viewer);return new DiscoverProfile(p.userId,p.name,age(p.birthDate),p.bio,p.city,distance(me.latitude,me.longitude,p.latitude,p.longitude),p.coffeePersonality,p.preferredPlan,p.preferredVibe,p.coffeesPerDay,p.favoriteCoffeeMoment,p.lookingFor,repo.coffees(p.userId),repo.photos(p.userId).stream().map(this::photo).toList());} public ShopDto shop(CoffeeShop s,double lat,double lng){return new ShopDto(s.id,s.name,s.address,s.neighborhood,distance(lat,lng,s.latitude,s.longitude),s.photoUrl,s.openingHours,s.rating,s.description,repo.vibes(s.id),s.latitude,s.longitude,s.providerId,s.reviewCount,s.openNow,s.priceLevel,s.website,s.phone,s.mapsUrl,s.types==null?List.of():Arrays.asList(s.types.split(",")),s.photoUrls,s.category);} public double distance(Double a,Double b,Double c,Double d){if(a==null||b==null||c==null||d==null)return 0;double p=Math.toRadians(c-a),q=Math.toRadians(d-b),v=Math.sin(p/2)*Math.sin(p/2)+Math.cos(Math.toRadians(a))*Math.cos(Math.toRadians(c))*Math.sin(q/2)*Math.sin(q/2);return Math.round(6371*2*Math.atan2(Math.sqrt(v),Math.sqrt(1-v))*10)/10.0;} }
